import React, { memo, useState, useCallback } from "react";
import "./ArchitectureDiagramLayered.css";

/* ============================================================
   🏗️  LAYERED ARCHITECTURE DIAGRAM

   Data-driven, authored per project via `details.architecture`
   in portfolio.js — the alternative to ArchitectureDiagramSimple's
   one generic "User → Frontend → API → AI Engine" fallback that
   every project without its own diagram used to share.

   Why layered rows instead of absolute x/y coordinates (the shape
   the older diagrams use): planes stack and reflow on narrow
   screens, and authoring a new project means listing nodes in
   order rather than hand-tuning percentages until they stop
   overlapping.

   Shape of `architecture`:
   {
     kind: "layered",
     boundary: { label, note },      // optional trust boundary
     legend: [{ tone, label }],      // optional
     layers: [{
       id, label, caption,
       nodes: [{ id, label, sub, icon, tone, tags: [] }],
     }],
     loops: [{ label, detail }],     // feedback / control annotations
     offBoundary: { label, nodes }   // anything OUTSIDE the boundary
   }
   ============================================================ */

const Node = ({ node, active, onSelect }) => (
  <button
    type="button"
    className={`adl-node adl-tone-${node.tone || "default"}${
      active ? " is-active" : ""
    }`}
    onClick={() => onSelect(active ? null : node.id)}
    aria-expanded={active}
  >
    {node.icon && (
      <span className="adl-node-icon" aria-hidden="true">
        {node.icon}
      </span>
    )}
    <span className="adl-node-body">
      <span className="adl-node-label">{node.label}</span>
      {node.sub && <span className="adl-node-sub">{node.sub}</span>}
    </span>
  </button>
);

/* The connector between two planes. `flow` names what actually travels
   down the wire, and `feedback` draws the return path alongside it — the
   cycle is the whole point of an agent loop, so it should be visible
   rather than implied. */
const Flow = ({ flow, feedback }) => (
  <div className={`adl-flow${feedback ? " has-feedback" : ""}`}>
    <div className="adl-flow-down">
      <span className="adl-flow-line" aria-hidden="true" />
      {flow && <span className="adl-flow-label">{flow}</span>}
      <span className="adl-flow-arrow" aria-hidden="true">
        ▼
      </span>
    </div>

    {feedback && (
      <div className="adl-flow-back">
        <span className="adl-flow-arrow up" aria-hidden="true">
          ▲
        </span>
        <span className="adl-flow-label back">{feedback}</span>
        <span className="adl-flow-line dashed" aria-hidden="true" />
      </div>
    )}
  </div>
);

const Layer = ({ layer, activeId, onSelect, isLast }) => (
  <div className="adl-layer">
    <div className="adl-layer-head">
      <span className="adl-layer-label">{layer.label}</span>
      {layer.caption && (
        <span className="adl-layer-caption">{layer.caption}</span>
      )}
    </div>

    <div className="adl-layer-nodes">
      {layer.nodes.map((n) => (
        <Node
          key={n.id}
          node={n}
          active={activeId === n.id}
          onSelect={onSelect}
        />
      ))}
    </div>

    {!isLast && <Flow flow={layer.flow} feedback={layer.feedback} />}
  </div>
);

const ArchitectureDiagramLayered = ({ architecture }) => {
  const [activeId, setActiveId] = useState(null);
  const select = useCallback((id) => setActiveId(id), []);

  if (!architecture || !Array.isArray(architecture.layers)) return null;

  const { boundary, layers, loops, legend, offBoundary } = architecture;

  // Flatten once so the detail panel can look a node up by id.
  const active = layers
    .flatMap((l) => l.nodes)
    .concat(offBoundary?.nodes || [])
    .find((n) => n.id === activeId);

  const stack = (
    <div className="adl-stack">
      {layers.map((layer, i) => (
        <Layer
          key={layer.id}
          layer={layer}
          activeId={activeId}
          onSelect={select}
          isLast={i === layers.length - 1}
        />
      ))}
    </div>
  );

  return (
    <div className="adl-root">
      {legend?.length > 0 && (
        <div className="adl-legend">
          {legend.map((l) => (
            <span className="adl-legend-item" key={l.label}>
              <i
                className={`adl-swatch adl-tone-${l.tone}`}
                aria-hidden="true"
              />
              {l.label}
            </span>
          ))}
        </div>
      )}

      {boundary ? (
        <div className="adl-boundary">
          <div className="adl-boundary-head">
            <span className="adl-boundary-badge">🔒 {boundary.label}</span>
            {boundary.note && (
              <span className="adl-boundary-note">{boundary.note}</span>
            )}
          </div>
          {stack}
        </div>
      ) : (
        stack
      )}

      {offBoundary?.nodes?.length > 0 && (
        <div className="adl-offboundary">
          <div className="adl-layer-head">
            <span className="adl-layer-label">{offBoundary.label}</span>
          </div>
          <div className="adl-layer-nodes">
            {offBoundary.nodes.map((n) => (
              <Node
                key={n.id}
                node={n}
                active={activeId === n.id}
                onSelect={select}
              />
            ))}
          </div>
        </div>
      )}

      {/* Click-through detail, so the boxes stay uncluttered */}
      <div
        className={`adl-detail${active ? " is-open" : ""}`}
        aria-live="polite"
      >
        {active ? (
          <>
            <strong className="adl-detail-title">
              {active.icon ? `${active.icon} ` : ""}
              {active.label}
            </strong>
            {active.detail && (
              <p className="adl-detail-text">{active.detail}</p>
            )}
            {active.tags?.length > 0 && (
              <div className="adl-detail-tags">
                {active.tags.map((t) => (
                  <span className="adl-tag" key={t}>
                    {t}
                  </span>
                ))}
              </div>
            )}
          </>
        ) : (
          <span className="adl-detail-hint">
            Select any component to see what it does.
          </span>
        )}
      </div>

      {loops?.length > 0 && (
        <div className="adl-loops">
          {loops.map((l) => (
            <div className="adl-loop" key={l.label}>
              <span className="adl-loop-label">↺ {l.label}</span>
              <span className="adl-loop-detail">{l.detail}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default memo(ArchitectureDiagramLayered);
