import React from "react";
import { FaFileDownload, FaPaperPlane } from "react-icons/fa";
import { downloadResume } from "../../utils/downloadResume";
import { getVisitorIntelligence } from "../../services/visitorIntelligence";
import ShareButtons from "./ShareButtons";
import "./share.css";

/**
 * End-of-page prompt for the pages people read longest: résumé, contact, and
 * a share row. `context` names the page in analytics ("project:rag-bot").
 * Plain anchor for /contact — this also renders inside the project modal,
 * which isn't guaranteed to sit inside a Router.
 */
const NextStepCTA = ({
  context,
  shareUrl,
  shareTitle,
  campaign,
  heading = "Building something similar?",
  body = "I design and ship production GenAI systems — retrieval pipelines, agents and the infrastructure around them. Happy to talk about roles or collaborations.",
}) => (
  <aside className="sx-cta" aria-label="Next steps">
    <div className="sx-cta-glow" aria-hidden="true" />
    <div className="sx-cta-text">
      <h3>{heading}</h3>
      <p>{body}</p>
    </div>
    <div className="sx-cta-actions">
      <button
        type="button"
        className="sx-cta-btn sx-cta-primary"
        onClick={() => downloadResume(`cta:${context}`)}
      >
        <FaFileDownload aria-hidden="true" /> Download résumé
      </button>
      <a
        className="sx-cta-btn"
        href="/contact"
        onClick={() =>
          getVisitorIntelligence().trackEvent("cta_contact", context)
        }
      >
        <FaPaperPlane aria-hidden="true" /> Get in touch
      </a>
    </div>
    {shareUrl && (
      <ShareButtons
        className="sx-cta-share"
        url={shareUrl}
        title={shareTitle}
        campaign={campaign}
        label="Know someone who'd find this useful?"
      />
    )}
  </aside>
);

export default NextStepCTA;
