/* ============================================
   🔗 SHARE LINKS
   Every shared URL carries utm_source=<network>, so a visit that comes back
   from a share is attributed on the admin dashboard (Audience → Campaigns)
   instead of landing in the "direct" bucket.
   ============================================ */

// Canonical host — shares made from localhost or a preview must still point
// at the real site.
export const SITE_URL = "https://laxman824.github.io";

/** Absolute canonical URL for a path ("/projects/rag-bot"). */
export const canonicalUrl = (path = "/") =>
  `${SITE_URL}${path.startsWith("/") ? path : `/${path}`}`;

/** url + utm_source / utm_medium / utm_campaign */
export const withUtm = (
  url,
  source,
  { medium = "social", campaign = "share" } = {}
) => {
  const u = new URL(url, SITE_URL);
  u.searchParams.set("utm_source", source);
  u.searchParams.set("utm_medium", medium);
  if (campaign) u.searchParams.set("utm_campaign", campaign);
  return u.toString();
};

const enc = encodeURIComponent;

/**
 * Share targets for one page. `campaign` names what was shared
 * ("project", "blog") so the dashboard can tell shares apart.
 */
export const shareTargets = ({ url, title = "", campaign }) => {
  const tagged = (source, medium) => withUtm(url, source, { medium, campaign });
  return {
    linkedin: {
      label: "LinkedIn",
      href: `https://www.linkedin.com/sharing/share-offsite/?url=${enc(
        tagged("linkedin")
      )}`,
    },
    twitter: {
      label: "X",
      href: `https://twitter.com/intent/tweet?text=${enc(title)}&url=${enc(
        tagged("twitter")
      )}`,
    },
    whatsapp: {
      label: "WhatsApp",
      href: `https://wa.me/?text=${enc(
        `${title} ${tagged("whatsapp")}`.trim()
      )}`,
    },
    reddit: {
      label: "Reddit",
      href: `https://www.reddit.com/submit?url=${enc(
        tagged("reddit")
      )}&title=${enc(title)}`,
    },
    hackernews: {
      label: "Hacker News",
      href: `https://news.ycombinator.com/submitlink?u=${enc(
        tagged("hackernews")
      )}&t=${enc(title)}`,
    },
    email: {
      label: "Email",
      href: `mailto:?subject=${enc(title)}&body=${enc(
        tagged("email", "email")
      )}`,
    },
    copy: { label: "Copy link", url: tagged("copy_link", "referral") },
    native: { label: "Share", url: tagged("native_share") },
  };
};
